// Performance monitoring utility
class PerformanceMonitor {
  constructor() {
    this.metrics = {
      imageLoadTimes: {},
      totalLoadTime: 0,
      criticalImagesLoaded: 0,
      totalImages: 0
    };
    this.startTime = performance.now();
  }

  // Start monitoring image load
  startImageLoad(url) {
    this.metrics.imageLoadTimes[url] = {
      startTime: performance.now(),
      loaded: false
    };
    this.metrics.totalImages++;
  }

  // End monitoring image load
  endImageLoad(url) {
    if (this.metrics.imageLoadTimes[url]) {
      const endTime = performance.now();
      const loadTime = endTime - this.metrics.imageLoadTimes[url].startTime;

      this.metrics.imageLoadTimes[url] = {
        ...this.metrics.imageLoadTimes[url],
        endTime,
        loadTime,
        loaded: true
      };

      this.metrics.criticalImagesLoaded++;
    }
  }

  // Get performance summary
  getPerformanceSummary() {
    const loadedImages = Object.values(this.metrics.imageLoadTimes).filter(img => img.loaded);
    const totalLoadTime = performance.now() - this.startTime;

    return {
      totalImages: this.metrics.totalImages,
      loadedImages: loadedImages.length,
      averageLoadTime: loadedImages.length > 0 
        ? loadedImages.reduce((sum, img) => sum + img.loadTime, 0) / loadedImages.length 
        : 0,
      totalLoadTime,
      slowestImage: loadedImages.length > 0 
        ? loadedImages.reduce((slowest, img) => img.loadTime > slowest.loadTime ? img : slowest)
        : null
    };
  }

  // Log performance metrics
  logPerformance() {
    const summary = this.getPerformanceSummary();
    console.log('🚀 Performance Summary:', summary);

    // Log slow images (> 2 seconds)
    const slowImages = Object.entries(this.metrics.imageLoadTimes)
      .filter(([url, data]) => data.loaded && data.loadTime > 2000)
      .map(([url, data]) => ({ url, loadTime: data.loadTime }));

    if (slowImages.length > 0) {
      console.warn('🐌 Slow loading images:', slowImages);
    }
  }

  // Reset metrics
  reset() {
    this.metrics = {
      imageLoadTimes: {},
      totalLoadTime: 0,
      criticalImagesLoaded: 0,
      totalImages: 0
    };
    this.startTime = performance.now();
  }
}

export default new PerformanceMonitor();
